package mapdb

import (
	"bytes"
	"fmt"
	"hash/maphash"
	"strings"
	"sync"

	"go.keploy.io/server/v3/pkg/models"
	"go.keploy.io/server/v3/pkg/platform/yaml"
	"go.keploy.io/server/v3/utils"
	"go.uber.org/zap"
	yamlLib "gopkg.in/yaml.v3"
)

// versionLine starts the comment line keploy writes at a mapping file's head
// (utils.GetVersionAsComment).
const versionLine = "# Generated by Keploy"

// header says when a writer starts a mapping file it writes with keploy's
// "# Generated by Keploy" line, as it always has: on every write
// (headerAlways), on a file it creates (headerOnNew), or never
// (headerNever). A head a person wrote comes first instead (commentHead).
type header int

const (
	headerNever header = iota
	headerOnNew
	headerAlways
)

// encodeOver encodes mapping in format to replace old, the file's bytes
// before (nil for a new file), as a writer of the file (testSetID's) writes
// it, whatever the proven switch. doc is the YAML document old parses to,
// which the writer decoded its mapping from (decodeInto; nil when old holds
// none). A YAML file keeps what a hand edit added to old (EncodeOver), and
// keploy says what it could not keep, so an edit is never lost without a
// word. A file that holds no hand edit is written as keploy always wrote
// it: the encoding, with keploy's line where the writer always put it (h).
// JSON is the encoding: it has no comments, and a field a person added to
// it is not kept, but named (jsonDropped), unless old is the file this db
// last encoded for the set, which holds none.
func (db *MappingDb) encodeOver(mapping *models.Mapping, format yaml.Format, old []byte, doc *yamlLib.Node, h header, testSetID string) ([]byte, error) {
	if format == yaml.FormatJSON {
		// old that is the file this db last encoded for the set, byte for
		// byte, holds only the fields keploy writes: naming the fields a
		// person added would decode it whole again on every flush of a
		// recording, which rewrites the file on each batch.
		if !db.jsonWritten.is(testSetID, old) {
			warnJSONDropped(db.logger, old, testSetID)
		}
		// data is nil when the encoding fails, and no file holds that.
		data, err := EncodeMappingF(mapping, db.logger, format)
		db.jsonWritten.set(testSetID, data)
		return data, err
	}
	return encodeOver(db.logger, mapping, format, old, doc, h, testSetID)
}

// EncodeOverF is mapping encoded in format to replace old, testSetID's
// mappings file before, as keploy's own writers rewrite one (MarkRecordedWith)
// and with what they say on logger: a YAML file keeps what a hand edit
// added to old (keepEdits) and the comment lines old starts with when they
// hold a person's comment, its "# Generated by Keploy" line brought up to
// this keploy, and puts no line of keploy's on a file whose head is that
// line alone or that has none; a warning names each hand edit it could not
// keep. A JSON file holds the fields keploy writes, each field a person
// added named in a warning. A writer outside this package that rewrites an
// existing file (enterprise's judged mark) writes it with this. Such a writer
// takes no set write lock, so it must not run beside a MappingDb write of the
// same set.
func EncodeOverF(logger *zap.Logger, mapping *models.Mapping, format yaml.Format, old []byte, testSetID string) ([]byte, error) {
	return encodeOver(logger, mapping, format, old, nil, headerNever, testSetID)
}

// encodeOver is MappingDb.encodeOver, its warnings on logger.
func encodeOver(logger *zap.Logger, mapping *models.Mapping, format yaml.Format, old []byte, doc *yamlLib.Node, h header, testSetID string) ([]byte, error) {
	if format == yaml.FormatJSON {
		warnJSONDropped(logger, old, testSetID)
		return EncodeMappingF(mapping, logger, format)
	}
	data, unkept, err := encodeYAMLOver(mapping, old, doc, nil, h)
	if err != nil {
		logger.Error("failed to marshal mapping", zap.Error(err))
		return nil, err
	}
	if unkept.Comments > 0 {
		logger.Warn(fmt.Sprintf("keploy rewrote the set's mappings file and dropped %d comment line(s) it could not place again", unkept.Comments),
			zap.String("testSetID", testSetID),
			zap.String("next_step", "keploy keeps the comment lines a mappings file starts with, comments on the keys it writes, and every field it does not know on the entries it writes; move a note to the top of the file"))
	}
	if len(unkept.Fields) > 0 {
		logger.Warn(fmt.Sprintf("keploy rewrote the set's mappings file and could not keep %d field(s) a hand edit added: each brings in more than %d YAML nodes through aliases", len(unkept.Fields), maxAliasNodes),
			zap.String("testSetID", testSetID), zap.Strings("fields", unkept.Fields),
			zap.String("next_step", "write the field's value out without aliases (*name), and keploy keeps it"))
	}
	if len(unkept.Dropped) > 0 {
		logger.Warn(fmt.Sprintf("keploy rewrote the set's mappings file and dropped %d field(s) a hand edit added to entries the new file does not have", len(unkept.Dropped)),
			zap.String("testSetID", testSetID), zap.Strings("fields", unkept.Dropped),
			zap.String("next_step", "the entry each field was on is gone from the file (removed, or its call recorded anew): add the field again where it belongs now"))
	}
	return data, nil
}

// warnJSONDropped says on logger which fields a person added to old,
// testSetID's mappings.json before a rewrite, the rewrite drops: a JSON
// mappings file keeps only the fields keploy writes (jsonDropped).
func warnJSONDropped(logger *zap.Logger, old []byte, testSetID string) {
	if fields := jsonDropped(old); len(fields) > 0 {
		logger.Warn(fmt.Sprintf("keploy rewrote the set's mappings file and dropped %d field(s) a hand edit added: a JSON mappings file keeps only the fields keploy writes", len(fields)),
			zap.String("testSetID", testSetID), zap.Strings("fields", fields),
			zap.String("next_step", "keep a note in mappings.yaml, which keeps a field a person adds, or outside the set"))
	}
}

// writtenFiles is, per test set, the file a MappingDb last encoded for it,
// as its hash (hash/maphash, seeded per process), so a file is known as
// keploy's own without keeping its bytes. Its zero value is empty.
type writtenFiles struct {
	sums sync.Map // test set ID -> uint64
}

// writtenSeed seeds the hashes of writtenFiles.
var writtenSeed = maphash.MakeSeed()

// set records data as the file encoded for testSetID.
func (w *writtenFiles) set(testSetID string, data []byte) {
	w.sums.Store(testSetID, maphash.Bytes(writtenSeed, data))
}

// is reports whether data is, byte for byte, the file last encoded for
// testSetID: false for a set none was encoded for.
func (w *writtenFiles) is(testSetID string, data []byte) bool {
	v, _ := w.sums.Load(testSetID)
	sum, ok := v.(uint64)
	return ok && sum == maphash.Bytes(writtenSeed, data)
}

// decodeInto decodes data, a mapping file's bytes in format, into m, and
// is the YAML document data parses to (nil for JSON). The file is parsed
// once: the writer decodes its mapping from the
// document, and its rewrite keeps the file's hand edits from it
// (encodeOver). It decodes as yaml.UnmarshalGeneric does.
func decodeInto(format yaml.Format, data []byte, m *models.Mapping) (*yamlLib.Node, error) {
	if format == yaml.FormatJSON {
		return nil, yaml.UnmarshalGeneric(format, data, m)
	}
	var doc yamlLib.Node
	if err := yamlLib.Unmarshal(data, &doc); err != nil {
		return nil, err
	}
	return &doc, doc.Decode(m)
}

// decodeOld is decodeInto for a writer: the mapping data holds, and its
// document; it logs what fails, as DecodeMappingF does.
func (db *MappingDb) decodeOld(data []byte, format yaml.Format) (*models.Mapping, *yamlLib.Node, error) {
	var m models.Mapping
	doc, err := decodeInto(format, data, &m)
	if err != nil {
		db.logger.Error("failed to unmarshal mapping data", zap.Error(err))
		return nil, nil, err
	}
	return &m, doc, nil
}

// Unkept is what a rewrite of a mapping file could not keep of the file it
// replaced (EncodeOver): how many of its comment lines; Fields, the fields a
// hand edit added that keploy could not write again (aliases bring in too
// much); and Dropped, the fields a hand edit added to items the new file
// does not have (a test it removed, a mock entry whose call it removed or
// recorded anew), which have nowhere to go. A mock entry the rewrite moved
// to another list keeps its fields there. Each field is named by where it
// was, as tests[o::TestB].mock_entries[mock-1].note.
type Unkept struct {
	Comments int
	Fields   []string
	Dropped  []string
}

// EncodeOver is mapping encoded as YAML to replace old, the mapping file's
// bytes before (nil for a new file), as keploy's own writers write it: with
// what a hand edit added to old (keepEdits), and the comment lines old
// starts with, its "# Generated by Keploy" line brought up to this keploy,
// or this keploy's line when old starts with no comment of a person's. A writer
// outside this package that builds the file anew (enterprise's per-test
// commit) writes it with this, and says what it could not keep.
//
// renames is how the rewrite named the mocks of old in the new file: nil
// when each mock keeps its name, so an old entry is the new entry of its
// name. Otherwise it names every mock the rewrite carried, one that keeps
// its name too (mock-2 to mock-2): an old entry naming mock n is the new
// entry naming renames[n], and an old entry whose mock renames lacks has no
// new entry: the rewrite did not carry that call, and a new entry that holds
// the name n now is another call, so a hand edit never moves to it
// (Unkept.Dropped). A caller that keeps the names of the mocks it carries
// passes the identity map of them, {"mock-1": "mock-1"}; one that renames
// them passes {old: new}, e.g. {"mock-1": "mock-3"}.
func EncodeOver(mapping *models.Mapping, old []byte, renames map[string]string) ([]byte, Unkept, error) {
	return encodeYAMLOver(mapping, old, nil, renames, headerAlways)
}

// encodeYAMLOver is EncodeOver with keploy's line where h puts it when old
// starts with no comment, and doc, the document old parses to when the
// caller parsed it (nil: keepEdits parses old).
func encodeYAMLOver(mapping *models.Mapping, old []byte, doc *yamlLib.Node, renames map[string]string, h header) ([]byte, Unkept, error) {
	data, err := yaml.MarshalGeneric(yaml.FormatYAML, mapping)
	if err != nil {
		return nil, Unkept{}, err
	}
	data, unkept := keepEdits(old, doc, data, renames)
	head := commentHead(old)
	switch {
	case len(head) > 0:
		data = append(head, data...)
	case h == headerAlways || h == headerOnNew && old == nil:
		data = append([]byte(utils.GetVersionAsComment()), data...)
	}
	return data, unkept, nil
}

// commentHead is the comment lines data starts with, and the blank lines
// between them, its "# Generated by Keploy" line replaced by this keploy's;
// nil when data starts with no comment, or with none but keploy's line: that
// line is keploy's, not a hand edit, and a writer puts it where it always
// did (header), so a file no person edited is written as keploy always wrote
// it. A document marker (---) or a directive (%YAML) among them is skipped:
// the writer writes neither, and YAML hangs the comments on both its sides
// on the first key. It reads data no further than its head.
func commentHead(data []byte) []byte {
	return scanHead(data, func(string) {})
}

// scanHead is commentHead, and hands each comment line of the head it reads
// to line as keploy knows it (headLine), keploy's line included, also when
// it is the only line and the head commentHead keeps is nil.
func scanHead(data []byte, line func(string)) []byte {
	var head bytes.Buffer
	blanks := 0
	edited := false
	for len(data) > 0 {
		raw := data
		if i := bytes.IndexByte(data, '\n'); i >= 0 {
			raw = data[:i+1]
		}
		data = data[len(raw):]
		t := bytes.TrimSpace(raw)
		if len(t) == 0 {
			blanks++
			continue
		}
		if string(t) == "---" || t[0] == '%' {
			continue
		}
		if t[0] != '#' {
			break
		}
		if head.Len() > 0 {
			head.WriteString(strings.Repeat("\n", blanks))
		}
		blanks = 0
		l := headLine(string(t))
		line(l)
		if l == versionLine {
			head.WriteString(utils.GetVersionAsComment())
			continue
		}
		edited = true
		head.Write(bytes.TrimRight(raw, "\r\n"))
		head.WriteByte('\n')
	}
	if !edited {
		return nil
	}
	return head.Bytes()
}

// headLine is a comment line of a mapping file as keploy knows it wherever
// it reads one, from the file's bytes (commentHead) or from the comments
// YAML hangs on its nodes (takeFileHead, commentLines): without the white
// space around it, which a line's place in the file adds (YAML keeps a
// line's trailing white space, not its indent), and keploy's "# Generated by
// Keploy" line whatever the keploy that wrote it, versionLine. So a line
// commentHead writes is the line YAML reads back from what it wrote.
func headLine(l string) string {
	l = strings.TrimSpace(l)
	if strings.HasPrefix(l, versionLine) {
		return versionLine
	}
	return l
}

// headComments is the comment lines of data's head, each as keploy knows it
// (headLine): the lines commentHead reads, which a rewrite keeps; keploy's
// line among them as versionLine, as often as the head holds it, also when
// the head holds no other line and commentHead keeps none.
func headComments(data []byte) []string {
	var out []string
	scanHead(data, func(l string) { out = append(out, l) })
	return out
}

// commentLines adds to out the comment lines of the YAML node n and of the
// nodes under it, each as keploy knows it (headLine), without keploy's
// "# Generated by Keploy" line.
func commentLines(n *yamlLib.Node, out []string) []string {
	if n == nil {
		return out
	}
	for _, c := range []string{n.HeadComment, n.LineComment, n.FootComment} {
		for _, l := range strings.Split(c, "\n") {
			if l = headLine(l); strings.HasPrefix(l, "#") && l != versionLine {
				out = append(out, l)
			}
		}
	}
	for _, child := range n.Content {
		out = commentLines(child, out)
	}
	return out
}

// uncounted is how many of the lines of old are not in kept, each line
// counted as often as it appears.
func uncounted(old, kept []string) int {
	have := make(map[string]int, len(kept))
	for _, l := range kept {
		have[l]++
	}
	n := 0
	for _, l := range old {
		if have[l] > 0 {
			have[l]--
			continue
		}
		n++
	}
	return n
}
